     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Notification Preferences</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1020;
         --panel: #141b34;
         --panel-border: #273255;
         --text: #f3f7ff;
         --muted: #a8b3d1;
         --accent: #7c9cff;
         --accent-strong: #98afff;
         --button-text: #081122;
         --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 24px;
         font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
         background:
           radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 32%),
           linear-gradient(180deg, #121937 0%, var(--bg) 100%);
         color: var(--text);
       }

       .app-shell {
         width: min(100%, 520px);
       }

       .card {
         background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
         border: 1px solid var(--panel-border);
         border-radius: 20px;
         padding: 32px;
         box-shadow: var(--shadow);
         backdrop-filter: blur(14px);
       }

       h1 {
         margin: 0 0 10px;
         font-size: clamp(1.9rem, 4vw, 2.4rem);
         line-height: 1.1;
       }

       .intro {
         margin: 0 0 24px;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 24px;
       }

       .form-field {
         margin: 0;
       }

       fieldset {
         margin: 0;
         padding: 0;
         border: 0;
         min-width: 0;
       }

       legend {
         margin-bottom: 16px;
         font-size: 1.05rem;
         font-weight: 600;
       }

       .radio-group {
         display: grid;
         gap: 12px;
       }

       .radio-option {
         display: flex;
         align-items: center;
         gap: 14px;
         padding: 16px 18px;
         border-radius: 14px;
         border: 1px solid rgba(168, 179, 209, 0.22);
         background: rgba(10, 16, 34, 0.72);
         cursor: pointer;
         transition: border-color 160ms ease, transform 160ms ease, background 160ms ease;
       }

       .radio-option:hover {
         border-color: rgba(124, 156, 255, 0.75);
         background: rgba(18, 27, 52, 0.95);
       }

       .radio-option:focus-within {
         outline: 2px solid var(--accent-strong);
         outline-offset: 3px;
         border-color: var(--accent-strong);
       }

       input[type="radio"] {
         margin: 0;
         width: 1.1rem;
         height: 1.1rem;
         accent-color: var(--accent);
       }

       .option-text {
         font-size: 1rem;
         font-weight: 500;
       }

       button[type="submit"] {
         border: 0;
         border-radius: 999px;
         padding: 14px 22px;
         font: inherit;
         font-weight: 700;
         color: var(--button-text);
         background: linear-gradient(135deg, var(--accent-strong), var(--accent));
         cursor: pointer;
         justify-self: start;
         box-shadow: 0 12px 28px rgba(124, 156, 255, 0.35);
       }

       button[type="submit"]:hover {
         transform: translateY(-1px);
       }

       button[type="submit"]:focus-visible {
         outline: 2px solid var(--accent-strong);
         outline-offset: 3px;
       }

       .status {
         min-height: 1.5rem;
         margin: 0;
         color: var(--muted);
       }

       @media (max-width: 480px) {
         .card {
           padding: 24px;
         }
       }

       @media (forced-colors: active) {
         .card,
         .radio-option,
         button[type="submit"] {
           border-color: ButtonText;
           background: Canvas;
           color: CanvasText;
           box-shadow: none;
         }

         .radio-option:focus-within,
         button[type="submit"]:focus-visible {
           outline-color: Highlight;
         }
       }
     </style>
   </head>
   <body>
     <main id="root"></main>
     <script>
       const notificationOptions = ["Email", "SMS", "Push Notifications"];

       function NotificationQuestion() {
         const options = notificationOptions
           .map(
             (option, index) => `
               <label class="radio-option" for="notification-${index}">
                 <input
                   id="notification-${index}"
                   type="radio"
                   name="notificationPreference"
                   value="${option}"
                   ${index === 0 ? "required" : ""}
                 />
                 <span class="option-text">${option}</span>
               </label>
             `
           )
           .join("");

         return `
           <div class="form-field">
             <fieldset>
               <legend>How do you prefer to receive notifications?</legend>
               <div class="radio-group">
                 ${options}
               </div>
             </fieldset>
           </div>
         `;
       }

       function FormSection() {
         return `
           <section class="card" aria-labelledby="page-title">
             <h1 id="page-title">Notification Preferences</h1>
             <p class="intro">Choose the one way you would like us to send updates.</p>
             <form id="preferences-form">
               ${NotificationQuestion()}
               <button type="submit">Submit</button>
               <p class="status" id="form-status" aria-live="polite"></p>
             </form>
           </section>
         `;
       }

       function App() {
         return `
           <div class="app-shell">
             ${FormSection()}
           </div>
         `;
       }

       document.getElementById("root").innerHTML = App();

       document.getElementById("preferences-form").addEventListener("submit", function (event) {
         event.preventDefault();
         const data = new FormData(event.currentTarget);
         const choice = data.get("notificationPreference");
         document.getElementById("form-status").textContent = choice
           ? `Preference saved: ${choice}.`
           : "Please select an option before submitting.";
       });
     </script>
   </body>
 </html>

